def Flocal(a: float, b: float, x1: float, x2: float, y1: float, y2: float, q: float) -> np.array:
    FF = np.zeros((24))
    
    FF[0] = 0
    FF[1] = 0
    FF[2] = q*(((x1**2-2*a*x1)/a)/2.0-((x2**2-2*a*x2)/a)/2.0)*(((y1**2-2*b*y1)/b)/2.0-((y2**2-2*b*y2)/b)/2.0)
    FF[3] = 0
