    FF[5] = (q*(x2**2/2.0-x1**2/2.0)*(((y1**2-2*b*y1)/b)/2.0-((y2**2-2*b*y2)/b)/2.0))/a
    FF[6] = 0
    FF[7] = 0
    FF[8] = (q*(x2**2/2.0-x1**2/2.0)*(y2**2/2.0-y1**2/2.0))/(a*b)
    FF[9] = 0
    FF[10] = 0
    FF[11] = (q*(((x1**2-2*a*x1)/a)/2.0-((x2**2-2*a*x2)/a)/2.0)*(y2**2/2.0-y1**2/2.0))/b
    FF[12] = 0
    FF[13] = 0
    FF[14] = 0
    FF[15] = 0
    FF[16] = 0
    FF[17] = 0
    FF[18] = 0
    FF[19] = 0
    FF[20] = 0
    FF[21] = 0
    FF[22] = 0
    FF[23] = 0
    
    return FF  

