    BB[3,22] = -((y*z)/(a*b*c))
    BB[3,23] = 0
    BB[4,0] = 0
    BB[4,1] = -(((1-x/a)*(1-y/b))/c)
    BB[4,2] = -(((1-x/a)*(1-z/c))/b)
    BB[4,3] = 0
    BB[4,4] = -((x*(1-y/b))/(a*c))
    BB[4,5] = -((x*(1-z/c))/(a*b))
